using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class B5ToneSurvey {static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=SceneManager.GetActiveScene();if(!scene.path.EndsWith("Level_B5_Isolation.unity"))throw new Exception("Expected active B5");string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/B5_Clinical_Tone_20261103"));Directory.CreateDirectory(r+"/Backup");File.Copy(scene.path,r+"/Backup/BeforeUserSave.unity",true);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");File.Copy(scene.path,r+"/Backup/CurrentUserCeilingBeforeFix.unity",true);File.Copy(scene.path+".meta",r+"/Backup/CurrentUserCeilingBeforeFix.unity.meta",true);var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var walls=all.Where(t=>t.name.Contains("Wall")&&P(t).Contains("/Geometry/")).Select(t=>new{t=t,m=t.GetComponent<MeshFilter>(),rr=t.GetComponent<Renderer>()}).Where(x=>x.m&&x.rr&&x.rr.enabled).Select(x=>new{path=P(x.t),position=V(x.t.position),rotation=V(x.t.eulerAngles),scale=V(x.t.lossyScale),boundsCenter=V(x.rr.bounds.center),boundsSize=V(x.rr.bounds.size),mesh=AssetDatabase.GetAssetPath(x.m.sharedMesh),vertices=x.m.sharedMesh.vertexCount,triangles=x.m.sharedMesh.triangles.Length/3,material=AssetDatabase.GetAssetPath(x.rr.sharedMaterial)}).ToArray();var ceilings=all.Where(t=>t.name.Contains("Ceiling")).Select(t=>new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale)}).ToArray();var lights=all.SelectMany(t=>t.GetComponents<Light>()).Select(l=>new{path=P(l.transform),position=V(l.transform.position),color=new[]{l.color.r,l.color.g,l.color.b},l.intensity,type=l.type.ToString(),bake=l.lightmapBakeType.ToString(),l.useColorTemperature,l.colorTemperature}).ToArray();var cols=all.SelectMany(t=>t.GetComponents<Collider>()).Select(c=>new{path=P(c.transform),type=c.GetType().Name,position=V(c.transform.position),rotation=V(c.transform.eulerAngles),scale=V(c.transform.lossyScale),enabled=c.enabled,trigger=c.isTrigger,boundsCenter=V(c.bounds.center),boundsSize=V(c.bounds.size)}).ToArray();File.WriteAllText(r+"/before.json",JsonConvert.SerializeObject(new{scene=scene.path,walls,ceilings,lights,colliders=cols},Formatting.Indented));return JsonConvert.SerializeObject(new{walls,ceilings=ceilings.Length,lights});}}
